from __future__ import annotations

import os
import shutil
import subprocess
from pathlib import Path

from secretscan.model import Module, ModuleStatus, Tool

CURATED_TOOLS = [
    ("nuclei", "--version"),
    ("gitleaks", "version"),
    ("trufflehog", "--version"),
    ("detect-secrets", "--version"),
    ("semgrep", "--version"),
    ("nmap", "--version"),
    ("openssl", "version"),
    ("git", "--version"),
    ("docker", "--version"),
    ("gh", "--version"),
    ("aws", "--version"),
    ("gcloud", "--version"),
    ("az", "--version"),
    ("kubectl", "version --client --short"),
    ("terraform", "--version"),
    ("python3", "--version"),
    ("python", "--version"),
    ("node", "--version"),
    ("go", "version"),
    ("rustc", "--version"),
    ("cargo", "--version"),
    ("ruby", "--version"),
    ("java", "-version"),
    ("brew", "--version"),
    ("pip3", "--version"),
    ("npm", "--version"),
    ("yarn", "--version"),
]

FALLBACK_DIRS = [
    "~/go/bin",
    "~/.cargo/bin",
    "~/.local/bin",
    "/opt/homebrew/bin",
    "/usr/local/bin",
]


def _get_version(name: str, version_flag: str) -> str:
    try:
        args = [name] + version_flag.split()
        result = subprocess.run(
            args, capture_output=True, text=True, timeout=10,
        )
        out = (result.stdout or result.stderr).strip()
        first_line = out.splitlines()[0] if out else ""
        return first_line[:120]
    except Exception:
        return ""


def _find_tool(name: str) -> str | None:
    path = shutil.which(name)
    if path:
        return path
    for d in FALLBACK_DIRS:
        expanded = os.path.expanduser(d)
        candidate = os.path.join(expanded, name)
        if os.path.isfile(candidate) and os.access(candidate, os.X_OK):
            return candidate
    return None


def _list_brew_packages() -> list[Tool]:
    tools: list[Tool] = []
    try:
        result = subprocess.run(
            ["brew", "list", "--formula", "-1"],
            capture_output=True, text=True, timeout=30,
        )
        if result.returncode == 0:
            for name in result.stdout.strip().splitlines():
                if name:
                    tools.append(Tool(name=name.strip(), source="brew"))
    except Exception:
        pass
    try:
        result = subprocess.run(
            ["brew", "list", "--cask", "-1"],
            capture_output=True, text=True, timeout=30,
        )
        if result.returncode == 0:
            for name in result.stdout.strip().splitlines():
                if name:
                    tools.append(Tool(name=name.strip(), source="brew-cask"))
    except Exception:
        pass
    return tools


def _list_pip_packages() -> list[Tool]:
    tools: list[Tool] = []
    try:
        result = subprocess.run(
            ["pip3", "list", "--format=freeze"],
            capture_output=True, text=True, timeout=30,
        )
        if result.returncode == 0:
            for line in result.stdout.strip().splitlines():
                parts = line.split("==")
                name = parts[0].strip()
                version = parts[1].strip() if len(parts) > 1 else ""
                if name:
                    tools.append(Tool(name=name, version=version, source="pip3"))
    except Exception:
        pass
    return tools


def _list_npm_global_packages() -> list[Tool]:
    tools: list[Tool] = []
    try:
        result = subprocess.run(
            ["npm", "list", "-g", "--depth=0", "--json"],
            capture_output=True, text=True, timeout=30,
        )
        if result.returncode == 0:
            import json
            data = json.loads(result.stdout)
            for name, info in data.get("dependencies", {}).items():
                ver = info.get("version", "") if isinstance(info, dict) else ""
                tools.append(Tool(name=name, version=ver, source="npm-global"))
    except Exception:
        pass
    return tools


def _list_go_bin() -> list[Tool]:
    tools: list[Tool] = []
    go_bin = os.path.expanduser("~/go/bin")
    if os.path.isdir(go_bin):
        for name in os.listdir(go_bin):
            full = os.path.join(go_bin, name)
            if os.path.isfile(full) and os.access(full, os.X_OK):
                tools.append(Tool(name=name, path=full, source="go/bin"))
    return tools


def tools_scan() -> tuple[list[Tool], ModuleStatus]:
    status = ModuleStatus(module=Module.INSTALLED_TOOLS)
    all_tools: list[Tool] = []

    for name, ver_flag in CURATED_TOOLS:
        status.attempted += 1
        path = _find_tool(name)
        if path:
            version = _get_version(path, ver_flag)
            source = "PATH" if shutil.which(name) else os.path.dirname(path)
            all_tools.append(Tool(
                name=name, version=version, path=path,
                source=source, curated=True,
            ))
            status.accessed += 1
        else:
            status.skipped += 1

    seen_names = {t.name for t in all_tools}
    for lister in [_list_brew_packages, _list_pip_packages, _list_npm_global_packages, _list_go_bin]:
        for tool in lister():
            if tool.name not in seen_names:
                all_tools.append(tool)
                seen_names.add(tool.name)

    return all_tools, status
